import{_ as o,r as n,o as p,c as l,e as s,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Repeater Field - October CMS - 4.x","titleTemplate":false,"description":"Form Widget","frontmatter":{"subtitle":"Form Widget","shortname":"Repeater"},"headers":[{"level":2,"title":"Grouped Repeaters","slug":"grouped-repeaters","link":"#grouped-repeaters","children":[]},{"level":2,"title":"Translatable Repeaters in Tailor","slug":"translatable-repeaters-in-tailor","link":"#translatable-repeaters-in-tailor","children":[{"level":3,"title":"Blueprint Configuration","slug":"blueprint-configuration","link":"#blueprint-configuration","children":[]},{"level":3,"title":"How It Works","slug":"how-it-works","link":"#how-it-works","children":[]}]},{"level":2,"title":"Example of Using Related Records","slug":"example-of-using-related-records","link":"#example-of-using-related-records","children":[]}],"relativePath":"4.x/element/form/widget-repeater.md","filePath":"4.x/element/form/widget-repeater.md"}'),i={name:"4.x/element/form/widget-repeater.md"};function u(d,a,k,g,h,m){const t=n("pre-heading"),e=n("post-heading");return p(),l("div",null,[s(t),a[0]||(a[0]=c("h1",null,"Repeater Field",-1)),s(e),a[1]||(a[1]=r(`<p><code>repeater</code> - renders a repeating set of form fields using a related record or <a href="./../../extend/system/models.html">jsonable attribute</a>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">extra_information</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> repeater
    <span class="token key atrule">form</span><span class="token punctuation">:</span>
        <span class="token key atrule">fields</span><span class="token punctuation">:</span>
            <span class="token key atrule">added_at</span><span class="token punctuation">:</span>
                <span class="token key atrule">label</span><span class="token punctuation">:</span> Date Added
                <span class="token key atrule">type</span><span class="token punctuation">:</span> datepicker
            <span class="token key atrule">details</span><span class="token punctuation">:</span>
                <span class="token key atrule">label</span><span class="token punctuation">:</span> Details
                <span class="token key atrule">type</span><span class="token punctuation">:</span> textarea
</code></pre></div><p>The following <a href="./../form-fields.html">field properties</a> are supported and commonly used.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>a name when displaying the form field to the user.</td></tr><tr><td><strong>default</strong></td><td>specifies a default array value, optional.</td></tr><tr><td><strong>comment</strong></td><td>places a descriptive comment below the field.</td></tr><tr><td><strong>form</strong></td><td>inline field definitions or a reference to form field definition file.</td></tr><tr><td><strong>prompt</strong></td><td>text to display for the create button. Default: Add new item.</td></tr><tr><td><strong>displayMode</strong></td><td>controls how the interface is displayed, as either <strong>accordion</strong> or <strong>builder</strong>. Default: <code>accordion</code></td></tr><tr><td><strong>useTabs</strong></td><td>shows tabs when enabled, allowing fields to specify a <code>tab</code> property. Default <code>false</code></td></tr><tr><td><strong>itemsExpanded</strong></td><td>if repeater items should be expanded by default when using accordion mode. Default: <code>true</code>.</td></tr><tr><td><strong>titleFrom</strong></td><td>name of field within items to use as the title for the collapsed item, optional.</td></tr><tr><td><strong>minItems</strong></td><td>minimum items required. Pre-displays those items when not using groups. For example if you set <code>minItems: 1</code> the first row will be displayed and not hidden.</td></tr><tr><td><strong>maxItems</strong></td><td>maximum number of items to allow within the repeater.</td></tr><tr><td><strong>groups</strong></td><td>references a group of form fields placing the repeater in group mode (see below). An inline definition can also be used.</td></tr><tr><td><strong>groupKeyFrom</strong></td><td>the group key attribute stored along with the saved data. Default: <code>_group</code></td></tr><tr><td><strong>showReorder</strong></td><td>displays an interface for sorting items. Default: true</td></tr><tr><td><strong>showDuplicate</strong></td><td>displays an interface for cloning items. Default: true</td></tr></tbody></table></div><p>The <code>titleFrom</code> property can be used to specify the value used when the repeater is collapsed.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">extra_information</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> repeater
    <span class="token key atrule">titleFrom</span><span class="token punctuation">:</span> title_when_collapsed
    <span class="token key atrule">form</span><span class="token punctuation">:</span>
        <span class="token key atrule">fields</span><span class="token punctuation">:</span>
            <span class="token comment"># ...</span>
            <span class="token key atrule">title_when_collapsed</span><span class="token punctuation">:</span>
                <span class="token key atrule">label</span><span class="token punctuation">:</span> This field is the title when collapsed
                <span class="token key atrule">type</span><span class="token punctuation">:</span> text
</code></pre></div><p>The repeater fields supports the use of tabs by setting the <code>useTabs</code> property to <code>true</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">extra_information</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> repeater
    <span class="token key atrule">useTabs</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
    <span class="token key atrule">form</span><span class="token punctuation">:</span>
        <span class="token key atrule">added_at</span><span class="token punctuation">:</span>
            <span class="token key atrule">label</span><span class="token punctuation">:</span> Date added
            <span class="token key atrule">type</span><span class="token punctuation">:</span> datepicker
            <span class="token key atrule">tab</span><span class="token punctuation">:</span> Date
        <span class="token key atrule">details</span><span class="token punctuation">:</span>
            <span class="token key atrule">label</span><span class="token punctuation">:</span> Details
            <span class="token key atrule">type</span><span class="token punctuation">:</span> textarea
            <span class="token key atrule">tab</span><span class="token punctuation">:</span> Details
</code></pre></div><h2 id="grouped-repeaters"><a href="#grouped-repeaters" class="header-anchor">#</a> Grouped Repeaters</h2><p>The repeater field supports a group mode using <code>groups</code> that allows a custom set of fields to be chosen for each iteration.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> repeater
    <span class="token key atrule">prompt</span><span class="token punctuation">:</span> Add content block
    <span class="token key atrule">groups</span><span class="token punctuation">:</span> $/acme/blog/config/fields_repeater.yaml
</code></pre></div><p>This is an example of a group configuration file, which would be located in <strong>/plugins/acme/blog/config/fields_repeater.yaml</strong>. For better organization, the <code>groups</code> can specify one file per group definition.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">groups</span><span class="token punctuation">:</span>
    <span class="token key atrule">textarea</span><span class="token punctuation">:</span> $/acme/blog/config/fields_textarea.yaml
    <span class="token key atrule">quote</span><span class="token punctuation">:</span> $/acme/blog/config/fields_quote.yaml
</code></pre></div><p>Alternatively, the definitions could be specified inline with the repeater. If the group key starts with an underscore (<code>_</code>) then it will be ignored.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">groups</span><span class="token punctuation">:</span>
    <span class="token key atrule">textarea</span><span class="token punctuation">:</span>
        <span class="token key atrule">name</span><span class="token punctuation">:</span> Textarea
        <span class="token key atrule">description</span><span class="token punctuation">:</span> Basic text field
        <span class="token key atrule">icon</span><span class="token punctuation">:</span> icon<span class="token punctuation">-</span>file<span class="token punctuation">-</span>text<span class="token punctuation">-</span>o
        <span class="token key atrule">fields</span><span class="token punctuation">:</span>
            <span class="token key atrule">text_area</span><span class="token punctuation">:</span>
                <span class="token key atrule">label</span><span class="token punctuation">:</span> Text Content
                <span class="token key atrule">type</span><span class="token punctuation">:</span> textarea
                <span class="token key atrule">size</span><span class="token punctuation">:</span> large

    <span class="token key atrule">quote</span><span class="token punctuation">:</span>
        <span class="token key atrule">name</span><span class="token punctuation">:</span> Quote
        <span class="token key atrule">description</span><span class="token punctuation">:</span> Quote item
        <span class="token key atrule">icon</span><span class="token punctuation">:</span> icon<span class="token punctuation">-</span>quote<span class="token punctuation">-</span>right
        <span class="token key atrule">fields</span><span class="token punctuation">:</span>
            <span class="token key atrule">quote_position</span><span class="token punctuation">:</span>
                <span class="token key atrule">span</span><span class="token punctuation">:</span> auto
                <span class="token key atrule">label</span><span class="token punctuation">:</span> Quote Position
                <span class="token key atrule">type</span><span class="token punctuation">:</span> radio
                <span class="token key atrule">options</span><span class="token punctuation">:</span>
                    <span class="token key atrule">left</span><span class="token punctuation">:</span> Left
                    <span class="token key atrule">center</span><span class="token punctuation">:</span> Center
                    <span class="token key atrule">right</span><span class="token punctuation">:</span> Right
            <span class="token key atrule">quote_content</span><span class="token punctuation">:</span>
                <span class="token key atrule">span</span><span class="token punctuation">:</span> auto
                <span class="token key atrule">label</span><span class="token punctuation">:</span> Details
                <span class="token key atrule">type</span><span class="token punctuation">:</span> textarea
</code></pre></div><p>Each group must specify a unique key and the definition supports the following options.</p><div class="table"><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>name</strong></td><td>the name of the group.</td></tr><tr><td><strong>description</strong></td><td>a brief description of the group.</td></tr><tr><td><strong>icon</strong></td><td>defines an icon for the group, optional.</td></tr><tr><td><strong>titleFrom</strong></td><td>name of a field for the item title, optional.</td></tr><tr><td><strong>fields</strong></td><td>form fields belonging to the group.</td></tr><tr><td><strong>useTabs</strong></td><td>shows tabs for the group only, optional.</td></tr></tbody></table></div><div class="custom-block tip"><p>The group key is stored along with the saved data as the <code>_group</code> attribute. This can be customized with the <code>groupKeyFrom</code> option.</p></div><h2 id="translatable-repeaters-in-tailor"><a href="#translatable-repeaters-in-tailor" class="header-anchor">#</a> Translatable Repeaters in Tailor</h2><p>When a <a href="./../../cms/tailor/blueprints.html">Tailor blueprint</a> uses <a href="./../../cms/multisite/tailor.html">multisite synchronization</a> (<code>multisite: sync</code>), repeater fields support three modes via the <code>translatable</code> property.</p><div class="table"><table tabindex="0"><thead><tr><th>Value</th><th>Behavior</th></tr></thead><tbody><tr><td><code>true</code> (default)</td><td>Each site has fully independent repeater items</td></tr><tr><td><code>false</code></td><td>All sites share the exact same repeater items (shared rows)</td></tr><tr><td><code>sync</code></td><td>Items are replicated per site with structure synced — adding, removing, or reordering items on one site propagates to all others</td></tr></tbody></table></div><p>The <code>sync</code> mode keeps the repeater <strong>structure</strong> (items, order) consistent across all sites while allowing individual sub-fields to have different values per site. This is useful for content like FAQs, file attachment lists, or specification tables where the list of items stays the same across languages but some values are translated.</p><h3 id="blueprint-configuration"><a href="#blueprint-configuration" class="header-anchor">#</a> Blueprint Configuration</h3><p>Set <code>translatable: sync</code> on the repeater field and mark individual sub-fields with <code>translatable: true</code> to allow per-site values.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">handle</span><span class="token punctuation">:</span> Blog\\Post
<span class="token key atrule">type</span><span class="token punctuation">:</span> stream
<span class="token key atrule">multisite</span><span class="token punctuation">:</span> sync

<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">attachments</span><span class="token punctuation">:</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> repeater
        <span class="token key atrule">translatable</span><span class="token punctuation">:</span> sync
        <span class="token key atrule">form</span><span class="token punctuation">:</span>
            <span class="token key atrule">fields</span><span class="token punctuation">:</span>
                <span class="token key atrule">file_title</span><span class="token punctuation">:</span>
                    <span class="token key atrule">type</span><span class="token punctuation">:</span> text
                    <span class="token key atrule">translatable</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>    <span class="token comment"># Different value per site</span>
                <span class="token key atrule">file_desc</span><span class="token punctuation">:</span>
                    <span class="token key atrule">type</span><span class="token punctuation">:</span> textarea        <span class="token comment"># Shared across all sites</span>
                <span class="token key atrule">file</span><span class="token punctuation">:</span>
                    <span class="token key atrule">type</span><span class="token punctuation">:</span> fileupload
                    <span class="token key atrule">mode</span><span class="token punctuation">:</span> file
                    <span class="token key atrule">maxFiles</span><span class="token punctuation">:</span> <span class="token number">1</span>           <span class="token comment"># Shared file across all sites</span>
                <span class="token key atrule">localized_image</span><span class="token punctuation">:</span>
                    <span class="token key atrule">type</span><span class="token punctuation">:</span> fileupload
                    <span class="token key atrule">mode</span><span class="token punctuation">:</span> image
                    <span class="token key atrule">maxFiles</span><span class="token punctuation">:</span> <span class="token number">1</span>
                    <span class="token key atrule">translatable</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>    <span class="token comment"># Different file per site</span>
</code></pre></div><p>In this example:</p><ul><li><strong>file_title</strong> has <code>translatable: true</code>, so each site can enter its own translated title. A globe icon indicates the field is translatable.</li><li><strong>file_desc</strong> does not set <code>translatable</code>, so its value is shared and propagated to all sites when saving.</li><li><strong>file</strong> is a file upload without <code>translatable</code>, so the uploaded file is shared across all sites automatically.</li><li><strong>localized_image</strong> is a file upload with <code>translatable: true</code>, so each site can upload a different image.</li></ul><h3 id="how-it-works"><a href="#how-it-works" class="header-anchor">#</a> How It Works</h3><p>When you save a record, structural changes (adding, removing, or reordering items) propagate to all synchronized sites automatically. Non-translatable sub-field values are copied, while translatable sub-field values are left untouched on each site.</p><p>Translatable sub-fields display a globe icon in the backend form, consistent with how translatable fields work on the parent entry.</p><div class="custom-block tip"><p>The <code>translatable</code> property on sub-fields is only meaningful when the repeater uses <code>translatable: sync</code>. Without it, sub-field <code>translatable</code> settings have no effect.</p></div><h2 id="example-of-using-related-records"><a href="#example-of-using-related-records" class="header-anchor">#</a> Example of Using Related Records</h2><p>The repeater form widget will automatically detect if the model attribute is a related field and use it. The following provides an example implementation that you may use. For example, if your model uses a <code>hasMany</code> relation that refers to a <strong>RepeaterItem</strong> model the repeater will use this related model for each item.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$hasMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;extra_information&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token class-name static-context">RepeaterItem</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;parent_id&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;delete&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span>
    <span class="token punctuation">]</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>A simple <a href="./../../extend/database/structure.html">database table schema</a> for the model can be defined that includes a reference to the parent model <code>id</code> and a serialized JSON <code>value</code> for dynamic attributes (see below).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme_blog_repeater_items&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">increments</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;parent_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">unsigned</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">index</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">mediumText</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;sort_order&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">timestamps</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The model extends the <code>October\\Rain\\Database\\ExpandoModel</code> base class to allow dynamic attributes set on the model and saved in the database, in JSON format. The model can <a href="./../../extend/database/attachments.html">include attachments</a> and any other related fields.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>ExpandoModel</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">RepeaterItem</span> <span class="token keyword">extends</span> <span class="token class-name">ExpandoModel</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Sortable</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$table</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;acme_blog_repeater_items&#39;</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$expandoPassthru</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;parent_id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;sort_order&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$attachMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;photos&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Finally, the repeater item can be specified as a form field with accompanying form field definitions, including fields that use <a href="./../../extend/database/relations.html">model relationships</a>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">extra_information</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> repeater
    <span class="token key atrule">form</span><span class="token punctuation">:</span>
        <span class="token key atrule">fields</span><span class="token punctuation">:</span>
            <span class="token key atrule">title</span><span class="token punctuation">:</span>
                <span class="token key atrule">label</span><span class="token punctuation">:</span> title
            <span class="token key atrule">is_enabled</span><span class="token punctuation">:</span>
                <span class="token key atrule">label</span><span class="token punctuation">:</span> Enabled
                <span class="token key atrule">type</span><span class="token punctuation">:</span> switch
            <span class="token key atrule">photos</span><span class="token punctuation">:</span>
                <span class="token key atrule">label</span><span class="token punctuation">:</span> Photos
                <span class="token key atrule">type</span><span class="token punctuation">:</span> fileupload
                <span class="token key atrule">mode</span><span class="token punctuation">:</span> image
</code></pre></div>`,40))])}const b=o(i,[["render",u]]);export{y as __pageData,b as default};
